XW += x[9]*1.4007000000000000e+01; // N
XW += x[10]*1.5015000000000001e+01; // NH
XW += x[11]*1.6023000000000000e+01; // NH2
XW += x[12]*1.7030999999999999e+01; // NH3
XW += x[13]*2.9021999999999998e+01; // NNH
XW += x[14]*3.0030000000000001e+01; // N2H2
XW += x[15]*3.1038000000000000e+01; // N2H3
