XW += x[29]*6.2003999999999998e+01; // NO3
XW += x[30]*6.3012000000000000e+01; // HNO3
// Now compute conversion
amrex::Real XWinv = 1.0/XW;
y[0] = x[0]*2.8013999999999999e+01*XWinv; 
